//! Unicode data the port readings lean on, carried as data
//! files beside this module and read at first use. The
//! printable ranges state which codepoints CPython's repr
//! leaves unescaped, and the name table states the character
//! names the string escape reading resolves under their
//! exact spellings, the formal aliases standing beside
//! them, the printable ranges generated by
//! tools/gen_printable_ranges.py from the interpreter's own
//! printable reading, and the name table generated by
//! tools/gen_unicode_names.py from the interpreter's own
//! unicode database and the system alias file. Two
//! families the database forms by rule, the Hangul
//! syllables and the CJK unified ideographs,
//! are resolved by rule here instead of standing in the
//! table, under the exact prefixes and ranges the
//! interpreter's own readings use.

use std::collections::HashMap;
use std::sync::OnceLock;

static PRINTABLE: OnceLock<Vec<(u32, u32)>> = OnceLock::new();
static NAMES: OnceLock<HashMap<String, u32>> = OnceLock::new();
static UNIFIED: OnceLock<Vec<(u32, u32)>> = OnceLock::new();

/// Read a data file of hexadecimal ranges, one range on
/// each line with its ends joined by a hyphen.
fn ranges_from(text: &str) -> Vec<(u32, u32)> {
    let mut ranges = Vec::new();
    for line in text.lines() {
        if let Some((lo, hi)) = line.split_once('-') {
            let lo = u32::from_str_radix(lo, 16).unwrap_or(0);
            let hi = u32::from_str_radix(hi, 16).unwrap_or(0);
            ranges.push((lo, hi));
        }
    }
    ranges
}

/// Whether a codepoint stands in a table of ranges, read
/// by binary search over the sorted ranges.
fn in_ranges(ranges: &[(u32, u32)], cp: u32) -> bool {
    let mut lo = 0usize;
    let mut hi = ranges.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (start, end) = ranges[mid];
        if cp < start {
            hi = mid;
        } else if cp > end {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

fn printable_ranges() -> &'static Vec<(u32, u32)> {
    PRINTABLE.get_or_init(|| ranges_from(include_str!("printable_ranges.txt")))
}

fn unified_ranges() -> &'static Vec<(u32, u32)> {
    UNIFIED.get_or_init(|| ranges_from(include_str!("unified_ranges.txt")))
}

/// Return true when CPython's repr leaves the character
/// unescaped, the printable reading of the interpreter.
pub fn is_printable(ch: char) -> bool {
    in_ranges(printable_ranges(), ch as u32)
}

fn name_table() -> &'static HashMap<String, u32> {
    NAMES.get_or_init(|| {
        let text = include_str!("unicode_names.txt");
        let mut map = HashMap::new();
        for line in text.lines() {
            if let Some((name, hex)) = line.rsplit_once(' ') {
                if let Ok(cp) = u32::from_str_radix(hex, 16) {
                    map.insert(name.to_string(), cp);
                }
            }
        }
        map
    })
}

const HANGUL_INITIALS: [&str; 19] = [
    "G", "GG", "N", "D", "DD", "R", "M", "B", "BB", "S", "SS", "", "J", "JJ", "C", "K", "T", "P",
    "H",
];
const HANGUL_MEDIALS: [&str; 21] = [
    "A", "AE", "YA", "YAE", "EO", "E", "YEO", "YE", "O", "WA", "WAE", "OE", "YO", "U", "WEO", "WE",
    "WI", "YU", "EU", "YI", "I",
];
const HANGUL_FINALS: [&str; 28] = [
    "", "G", "GG", "GS", "N", "NJ", "NH", "D", "L", "LG", "LM", "LB", "LS", "LT", "LP", "LH", "M",
    "B", "BS", "S", "SS", "NG", "J", "C", "K", "T", "P", "H",
];

/// Resolve an algorithmic Hangul syllable name to its
/// codepoint, or None when the name is not one.
fn hangul_lookup(name: &str) -> Option<u32> {
    let rest = name.strip_prefix("HANGUL SYLLABLE ")?;
    if rest.is_empty() {
        return None;
    }
    // Try each initial, then a medial, then an optional final,
    // the syllable the three parts compose.
    for (ii, initial) in HANGUL_INITIALS.iter().enumerate() {
        let after = if initial.is_empty() {
            rest
        } else {
            match rest.strip_prefix(initial) {
                Some(after) => after,
                None => continue,
            }
        };
        for (mi, medial) in HANGUL_MEDIALS.iter().enumerate() {
            let tail = match after.strip_prefix(medial) {
                Some(tail) => tail,
                None => continue,
            };
            for (fi, final_) in HANGUL_FINALS.iter().enumerate() {
                let matches = if fi == 0 {
                    tail.is_empty()
                } else {
                    tail == *final_
                };
                if matches {
                    let code = 0xAC00 + ((ii as u32 * 21) + mi as u32) * 28 + fi as u32;
                    return Some(code);
                }
            }
        }
    }
    None
}

/// Resolve a character name to its codepoint, the reading
/// the string escape for a named character makes, or None
/// when the name stands unknown. The Hangul syllables and
/// the unified ideographs resolve by rule under their exact
/// prefixes, and every other name resolves against the
/// table under its exact spelling, the query folded to
/// upper case in ASCII the way the interpreter folds it,
/// so a doubled space or a moved hyphen stands unknown.
pub fn lookup_name(name: &str) -> Option<char> {
    if let Some(cp) = hangul_lookup(name) {
        return char::from_u32(cp);
    }
    if let Some(cp) = unified_lookup(name) {
        return char::from_u32(cp);
    }
    let folded = name.to_ascii_uppercase();
    name_table().get(&folded).and_then(|cp| char::from_u32(*cp))
}

/// Resolve a CJK unified ideograph name to its codepoint,
/// or None when the name is not one. The suffix is four or
/// five upper case hexadecimal digits, no more and no
/// fewer, and the codepoint it names must stand in one of
/// the unified ranges, the readings the interpreter makes
/// of the family.
fn unified_lookup(name: &str) -> Option<u32> {
    let hex = name.strip_prefix("CJK UNIFIED IDEOGRAPH-")?;
    if hex.len() < 4 || hex.len() > 5 {
        return None;
    }
    if !hex
        .bytes()
        .all(|b| b.is_ascii_digit() || (b'A'..=b'F').contains(&b))
    {
        return None;
    }
    let cp = u32::from_str_radix(hex, 16).ok()?;
    if in_ranges(unified_ranges(), cp) {
        Some(cp)
    } else {
        None
    }
}
